21	        foreach (var m in mensajes)
22	        {
23	            if (m.Rol == "tool")
24	                msgs.Add(new JsonObject { ["role"] = "tool", ["tool_call_id"] = m.ToolCallId, ["content"] = m.Contenido });
25	            else if (m.Rol == "assistant" && m.Llamadas is { Count: > 0 })
26	            {
27	                var calls = new JsonArray();
28	                foreach (var l in m.Llamadas)
29	                {
30	                    var call = new JsonObject
31	                    {
32	                        ["id"] = l.Id,
33	                        ["type"] = "function",
34	                        ["function"] = new JsonObject { ["name"] = l.Nombre, ["arguments"] = l.ArgumentosJson },
35	                    };
36	                    // Gemini exige reenviar extra_content (thought_signature) tal cual lo emitió.
37	                    if (!string.IsNullOrEmpty(l.ExtraJson))
38	                        call["extra_content"] = JsonNode.Parse(l.ExtraJson);
39	                    calls.Add(call);
40	                }
41	                msgs.Add(new JsonObject
42	                {
43	                    ["role"] = "assistant",
44	                    ["content"] = string.IsNullOrEmpty(m.Contenido) ? null : m.Contenido,
45	                    ["tool_calls"] = calls,
46	                });
47	            }
48	            else
49	                msgs.Add(new JsonObject { ["role"] = m.Rol, ["content"] = m.Contenido });
50	        }
51	
52	        var cuerpo = new JsonObject { ["model"] = modelo, ["messages"] = msgs, ["max_tokens"] = MaxTokens };
53	        if (herramientas.Count > 0)
54	        {
55	            var tools = new JsonArray();
56	            foreach (var h in herramientas)
57	                tools.Add(new JsonObject
58	                {
59	                    ["type"] = "function",
60	                    ["function"] = new JsonObject
61	                    {
62	                        ["name"] = h.Nombre,
63	                        ["description"] = h.Descripcion,
64	                        ["parameters"] = LlmHttp.ParseOVacio(h.ParametrosJsonSchema),
65	                    },
66	                });
67	            cuerpo["tools"] = tools;
68	        }
69	
70	        using var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/chat/completions");
71	        req.Headers.TryAddWithoutValidation("Authorization", "Bearer " + cfg["LLM_API_KEY"]?.Trim());
72	        using var doc = await LlmHttp.EnviarAsync(fabrica.CreateClient("llm"), req, cuerpo, ct);
73	
74	        try
75	        {
76	            var raiz = doc.RootElement;
77	            var mensaje = raiz.GetProperty("choices")[0].GetProperty("message");
78	            string? texto = mensaje.TryGetProperty("content", out var c) && c.ValueKind == JsonValueKind.String ? c.GetString() : null;
79	            var llamadas = new List<LlmLlamadaHerramienta>();
80	            if (mensaje.TryGetProperty("tool_calls", out var tc) && tc.ValueKind == JsonValueKind.Array)
81	            {
82	                var n = 0;
83	                foreach (var t in tc.EnumerateArray())
84	                {
85	                    var f = t.GetProperty("function");
86	                    var id = t.TryGetProperty("id", out var i) && i.ValueKind == JsonValueKind.String && !string.IsNullOrEmpty(i.GetString())
87	                        ? i.GetString()! : $"call_{n}";
88	                    var args = f.TryGetProperty("arguments", out var a)
89	                        ? (a.ValueKind == JsonValueKind.String ? a.GetString()! : a.GetRawText()) : "{}";
90	                    // Solo un objeto JSON se guarda y reenvía; otro tipo se descarta. Tampoco se guarda uno de más de 8 KB:
91	                    // se reenvía en cada vuelta, así que un proveedor hostil podría inflar tokens y memoria.
92	                    var extra = t.TryGetProperty("extra_content", out var ex) && ex.ValueKind == JsonValueKind.Object
93	                        ? ex.GetRawText() : null;
94	                    if (extra is not null && extra.Length > 8 * 1024) extra = null;
95	                    llamadas.Add(new(id, f.GetProperty("name").GetString()!, string.IsNullOrWhiteSpace(args) ? "{}" : args, extra));
96	                    n++;
97	                }
98	            }
99	            var uso = raiz.TryGetProperty("usage", out var u) ? u : default;
100	            return new(texto, llamadas, new(LlmHttp.Entero(uso, "prompt_tokens"), LlmHttp.Entero(uso, "completion_tokens")));
101	        }
102	        catch (Exception e) when (e is KeyNotFoundException or InvalidOperationException or IndexOutOfRangeException or ArgumentOutOfRangeException)
103	        {
104	            throw new LlmException("El proveedor del modelo devolvió una respuesta sin los campos esperados.");
105	        }
106	    }
107	}
