7	public class AnthropicClient(IHttpClientFactory fabrica, IConfiguration cfg) : ILlmClient
8	{
9	    public const string BaseDefecto = "https://api.anthropic.com";
10	    public const string ModeloDefecto = "claude-haiku-4-5";
11	    const int MaxTokens = 2048;
12	
13	    public async Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
14	        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
15	    {
16	        var baseUrl = (string.IsNullOrWhiteSpace(cfg["LLM_BASE_URL"]) ? BaseDefecto : cfg["LLM_BASE_URL"]!).TrimEnd('/');
17	        var modelo = string.IsNullOrWhiteSpace(cfg["LLM_MODEL"]) ? ModeloDefecto : cfg["LLM_MODEL"]!;
18	
19	        var msgs = new JsonArray();
20	        JsonArray? resultados = null; // bloques tool_result consecutivos
21	        foreach (var m in mensajes)
22	        {
23	            if (m.Rol == "tool")
24	            {
25	                if (resultados == null)
26	                {
27	                    resultados = [];
28	                    msgs.Add(new JsonObject { ["role"] = "user", ["content"] = resultados });
29	                }
30	                resultados.Add(new JsonObject { ["type"] = "tool_result", ["tool_use_id"] = m.ToolCallId, ["content"] = m.Contenido });
31	                continue;
32	            }
33	            resultados = null;
34	            var bloques = new JsonArray();
35	            if (!string.IsNullOrEmpty(m.Contenido) || m.Llamadas is not { Count: > 0 })
36	                bloques.Add(new JsonObject { ["type"] = "text", ["text"] = m.Contenido });
37	            if (m.Rol == "assistant" && m.Llamadas != null)
38	                foreach (var l in m.Llamadas)
39	                    bloques.Add(new JsonObject
40	                    {
41	                        ["type"] = "tool_use",
42	                        ["id"] = l.Id,
43	                        ["name"] = l.Nombre,
44	                        ["input"] = LlmHttp.ParseOVacio(l.ArgumentosJson),
45	                    });
46	            msgs.Add(new JsonObject { ["role"] = m.Rol == "assistant" ? "assistant" : "user", ["content"] = bloques });
47	        }
48	
49	        var cuerpo = new JsonObject
50	        {
51	            ["model"] = modelo,
52	            ["max_tokens"] = MaxTokens,
53	            ["system"] = new JsonArray
54	            {
55	                new JsonObject
56	                {
57	                    ["type"] = "text",
58	                    ["text"] = sistema,
59	                    ["cache_control"] = new JsonObject { ["type"] = "ephemeral" },
60	                },
61	            },
62	            ["messages"] = msgs,
63	        };
64	        if (herramientas.Count > 0)
65	        {
66	            var tools = new JsonArray();
67	            foreach (var h in herramientas)
68	                tools.Add(new JsonObject
69	                {
70	                    ["name"] = h.Nombre,
71	                    ["description"] = h.Descripcion,
72	                    ["input_schema"] = LlmHttp.ParseOVacio(h.ParametrosJsonSchema),
73	                });
74	            cuerpo["tools"] = tools;
75	        }
76	
77	        using var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/v1/messages");
78	        req.Headers.TryAddWithoutValidation("x-api-key", cfg["LLM_API_KEY"]?.Trim());
79	        req.Headers.TryAddWithoutValidation("anthropic-version", "2023-06-01");
80	        using var doc = await LlmHttp.EnviarAsync(fabrica.CreateClient("llm"), req, cuerpo, ct);
81	
82	        try
83	        {
84	            var raiz = doc.RootElement;
85	            var texto = new StringBuilder();
86	            var llamadas = new List<LlmLlamadaHerramienta>();
87	            foreach (var b in raiz.GetProperty("content").EnumerateArray())
88	            {
89	                var tipo = b.GetProperty("type").GetString();
90	                if (tipo == "text" && b.TryGetProperty("text", out var t) && t.ValueKind == JsonValueKind.String)
91	                    texto.Append(t.GetString());
92	                else if (tipo == "tool_use")
93	                    llamadas.Add(new(b.GetProperty("id").GetString()!, b.GetProperty("name").GetString()!,
94	                        b.TryGetProperty("input", out var inp) ? inp.GetRawText() : "{}"));
95	            }
96	            var uso = raiz.TryGetProperty("usage", out var u) ? u : default;
97	            var entrada = LlmHttp.Entero(uso, "input_tokens") + LlmHttp.Entero(uso, "cache_creation_input_tokens")
98	                          + LlmHttp.Entero(uso, "cache_read_input_tokens");
99	            return new(texto.Length > 0 ? texto.ToString() : null, llamadas, new(entrada, LlmHttp.Entero(uso, "output_tokens")));
100	        }
101	        catch (Exception e) when (e is KeyNotFoundException or InvalidOperationException)
102	        {
103	            throw new LlmException("El proveedor del modelo devolvió una respuesta sin los campos esperados.");
104	        }
105	    }
106	}
