7	// Precio USD por millón de tokens. Ausente = 0; un valor no numérico o negativo impide arrancar.
8	public record Precios(double EntradaMtok, double SalidaMtok)
9	{
10	    public static Precios Desde(IConfiguration cfg) =>
11	        new(Leer(cfg, "LLM_PRECIO_ENTRADA_MTOK"), Leer(cfg, "LLM_PRECIO_SALIDA_MTOK"));
12	
13	    static double Leer(IConfiguration cfg, string nombre)
14	    {
15	        var s = cfg[nombre]?.Trim();
16	        if (string.IsNullOrEmpty(s)) return 0;
17	        if (!double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out var v) || !double.IsFinite(v) || v < 0)
18	            throw new InvalidOperationException($"{nombre} debe ser un número no negativo (USD por millón de tokens, con punto decimal).");
19	        if (v > MaxPrecio)
20	            throw new InvalidOperationException($"{nombre} no puede superar {MaxPrecio:0} USD por millón de tokens.");
21	        return v + 0d; // normaliza -0
22	    }
23	
24	    public const double MaxPrecio = 1_000_000d;
25	
26	    // Siempre finito y >= 0 (nunca -0, NaN ni Infinity).
27	    public double Costo(long tokensEntrada, long tokensSalida)
28	    {
29	        var c = (Math.Max(0, tokensEntrada) * Math.Clamp(EntradaMtok, 0, MaxPrecio)
30	                 + Math.Max(0, tokensSalida) * Math.Clamp(SalidaMtok, 0, MaxPrecio)) / 1_000_000d;
31	        return double.IsFinite(c) && c > 0 ? c : 0d;
32	    }
33	}
