35	public record RegistroAuditoria(
36	    string? Rol, string? Id, string? Pregunta,
37	    IReadOnlyList<string> EstudiantesConsultados, IReadOnlyList<Cita> Citas,
38	    int Codigo, int Tokens, double CostoUsd);
39	
40	// Una línea JSON por pregunta. Un fallo al escribir nunca tumba la petición.
41	public class Auditoria(IConfiguration cfg, ILogger<Auditoria> logger)
42	{
43	    const int MaxPregunta = 10_000;
44	    static readonly JsonSerializerOptions Opciones = new()
45	    {
46	        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
47	        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
48	    };
49	
50	    readonly object candado = new();
51	    readonly string ruta = Path.GetFullPath(
52	        string.IsNullOrWhiteSpace(cfg["Auditoria:Ruta"]) ? Path.Combine("logs", "auditoria.jsonl") : cfg["Auditoria:Ruta"]!);
53	
54	    public void Registrar(RegistroAuditoria r)
55	    {
56	        string linea;
57	        try
58	        {
59	            var llave = cfg["LLM_API_KEY"]?.Trim();
60	            string? Limpiar(string? s) =>
61	                s != null && !string.IsNullOrEmpty(llave) ? s.Replace(llave, "[REDACTADO]", StringComparison.Ordinal) : s;
62	
63	            var pregunta = Limpiar(r.Pregunta);
64	            if (pregunta is { Length: > MaxPregunta }) pregunta = pregunta[..MaxPregunta];
65	            linea = JsonSerializer.Serialize(new
66	            {
67	                fechaHora = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture),
68	                rol = Limpiar(r.Rol),
69	                id = Limpiar(r.Id),
70	                pregunta,
71	                estudiantesConsultados = r.EstudiantesConsultados.Select(i => Limpiar(i)).ToList(),
72	                citas = r.Citas.Select(c => new { documento = c.Documento, seccion = c.Seccion }).ToList(),
73	                codigo = r.Codigo,
74	                tokens = r.Tokens,
75	                costoUsd = r.CostoUsd,
76	            }, Opciones);
77	        }
78	        catch (Exception e)
79	        {
80	            logger.LogError("No se pudo construir la línea de auditoría ({Tipo}).", e.GetType().Name);
81	            return;
82	        }
83	
84	        logger.LogInformation("Auditoria {Linea}", linea);
85	        try
86	        {
87	            lock (candado)
88	            {
89	                var dir = Path.GetDirectoryName(ruta);
90	                if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
91	                File.AppendAllText(ruta, linea + "\n");
92	            }
93	        }
94	        catch (Exception e)
95	        {
96	            logger.LogError("No se pudo escribir la auditoría ({Tipo}).", e.GetType().Name);
97	        }
98	    }
99	}
