110	                (conSemestre ? c.Estudiantes : c.Coordinadores).Add(p);
111	        }
112	        var repetidos = c.Estudiantes.Select(x => x.Id).Intersect(c.Coordinadores.Select(x => x.Id)).ToList();
113	        if (repetidos.Count > 0)
114	            throw new InvalidDataException($"Ids presentes como estudiante y coordinador: {string.Join(", ", repetidos)}.");
115	        if (c.Estudiantes.Count == 0 || c.Coordinadores.Count == 0)
116	            throw new InvalidDataException("No se encontraron estudiantes y coordinadores en los datos; la regla R2 no se puede comprobar.");
