133	public static class Evaluador
134	{
135	    public static readonly JsonSerializerOptions JsonOpts = new() { PropertyNameCaseInsensitive = true, UnmappedMemberHandling = System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow };
136	
137	    /// <summary>Minúsculas, sin tildes, y coma decimal equivale a punto.</summary>
138	    public static string Normalizar(string s)
139	    {
140	        var d = s.Normalize(NormalizationForm.FormD);
141	        var sb = new StringBuilder(d.Length);
142	        foreach (var ch in d)
143	        {
144	            if (CharUnicodeInfo.GetUnicodeCategory(ch) == UnicodeCategory.NonSpacingMark) continue;
145	            sb.Append(char.ToLowerInvariant(ch));
146	        }
147	        return Regex.Replace(sb.ToString(), @"(?<=\d),(?=\d)", ".");
148	    }
