150	    public static ResultadoCaso SinResultado(Caso caso, string motivo) => new()
151	    {
152	        Id = caso.Id, Escenario = caso.Escenario, Estado = Estado.SinResultado, Motivos = { motivo },
153	    };
154	
155	    public static ResultadoCaso Evaluar(Caso caso, RespuestaHttp resp, Corpus corpus, string? llave)
156	    {
157	        var r = new ResultadoCaso { Id = caso.Id, Escenario = caso.Escenario, Codigo = resp.Codigo };
158	        var aceptados = caso.CodigosAceptados is { Count: > 0 } ? caso.CodigosAceptados : new List<int> { caso.CodigoEsperado };
159	        if (!aceptados.Contains(resp.Codigo))
160	            r.Motivos.Add($"código {resp.Codigo}, esperado {string.Join("/", aceptados)}");
161	
162	        ReglaR2(caso, resp.Cuerpo, corpus, llave, r);
163	
164	        if (resp.Codigo == 200) Evaluar200(caso, resp.Cuerpo, corpus, r);
165	
166	        // Una violación de reglas duras también reprueba el caso.
167	        r.Motivos.AddRange(r.ViolacionesReglasDuras);
168	        r.Estado = r.Motivos.Count == 0 ? Estado.Ok : Estado.Falla;
169	        return r;
170	    }
171	
172	    static void Evaluar200(Caso caso, string cuerpo, Corpus corpus, ResultadoCaso r)
173	    {
174	        JsonDocument doc;
175	        try { doc = JsonDocument.Parse(cuerpo); }
176	        catch (JsonException) { r.Motivos.Add("el cuerpo 200 no es JSON válido"); return; }
177	        using (doc)
178	        {
179	            var raiz = doc.RootElement;
180	            if (raiz.ValueKind != JsonValueKind.Object) { r.Motivos.Add("el cuerpo 200 no es un objeto"); return; }
181	            var esperados = new[] { "respuesta", "citas", "usoDatosEstudiante", "tokens", "costoUsd" };
182	            foreach (var p in raiz.EnumerateObject())
183	                if (!esperados.Contains(p.Name)) r.Motivos.Add($"campo extra en contrato: {p.Name}");
184	
185	            string? respuesta = null;
186	            bool? uso = null;
187	            var citas = new List<CitaCaso>();
188	            var contratoOk = true;
189	
190	            if (raiz.TryGetProperty("respuesta", out var rp) && rp.ValueKind == JsonValueKind.String) respuesta = rp.GetString();
191	            else { r.Motivos.Add("contrato: 'respuesta' ausente o no es string"); contratoOk = false; }
192	
193	            if (raiz.TryGetProperty("citas", out var cs) && cs.ValueKind == JsonValueKind.Array)
194	            {
195	                foreach (var c in cs.EnumerateArray())
196	                {
197	                    if (c.ValueKind == JsonValueKind.Object
198	                        && c.TryGetProperty("documento", out var dd) && dd.ValueKind == JsonValueKind.String
199	                        && c.TryGetProperty("seccion", out var ss) && ss.ValueKind == JsonValueKind.String
200	                        && c.EnumerateObject().Count() == 2)
201	                        citas.Add(new CitaCaso(dd.GetString()!, ss.GetString()!));
202	                    else { r.Motivos.Add("contrato: cita mal formada"); contratoOk = false; }
203	                }
204	            }
205	            else { r.Motivos.Add("contrato: 'citas' ausente o no es arreglo"); contratoOk = false; }
206	
207	            if (raiz.TryGetProperty("usoDatosEstudiante", out var u)
208	                && (u.ValueKind == JsonValueKind.True || u.ValueKind == JsonValueKind.False))
209	                uso = u.GetBoolean();
210	            else { r.Motivos.Add("contrato: 'usoDatosEstudiante' ausente o no es booleano"); contratoOk = false; }
211	
212	            if (raiz.TryGetProperty("tokens", out var t) && t.ValueKind == JsonValueKind.Number && t.TryGetInt64(out var tk))
213	            {
214	                if (tk < 0) r.Motivos.Add("tokens negativo");
215	                else r.Tokens = tk;
216	            }
217	            else { r.Motivos.Add("contrato: 'tokens' ausente o no es entero"); contratoOk = false; }
218	
219	            if (raiz.TryGetProperty("costoUsd", out var co) && co.ValueKind == JsonValueKind.Number)
220	            {
221	                var v = co.GetDouble();
222	                if (v < 0) r.Motivos.Add("costoUsd negativo");
223	                else r.CostoUsd = v;
224	            }
225	            else { r.Motivos.Add("contrato: 'costoUsd' ausente o no es número"); contratoOk = false; }
226	
227	            r.Conto200 = contratoOk;
228	
229	            // R1: toda cita devuelta debe existir literalmente en el índice.
230	            foreach (var c in citas)
231	                if (!corpus.Citas.Contains((c.Documento, c.Seccion)))
232	                    r.ViolacionesReglasDuras.Add($"R1 cita inexistente: {c.Documento} / {c.Seccion}");
233	
234	            foreach (var e in caso.CitasEsperadas ?? new())
235	                if (!citas.Any(c => c.Documento == e.Documento && c.Seccion == e.Seccion))
236	                    r.Motivos.Add($"falta cita {e.Documento} / {e.Seccion}");
237	
238	            if (uso is not null && caso.UsoDatosEstudianteEsperado is bool esp && uso != esp)
239	                r.Motivos.Add($"usoDatosEstudiante {uso}, esperado {esp}");
240	
241	            // RN-03: sin citas esperadas ni datos, la respuesta no debe citar nada.
242	            if ((caso.CitasEsperadas is null || caso.CitasEsperadas.Count == 0)
243	                && caso.UsoDatosEstudianteEsperado == false && citas.Count > 0)
244	                r.Motivos.Add("citas debía ser vacío (RN-03)");
245	
246	            if (respuesta is not null && string.IsNullOrWhiteSpace(respuesta))
247	                r.Motivos.Add("respuesta vacía en un 200");
248	
249	            if (respuesta is not null)
250	            {
251	                var n = Normalizar(respuesta);
252	                foreach (var k in caso.PalabrasClave ?? new())
253	                    if (!n.Contains(Normalizar(k))) r.Motivos.Add($"falta palabra clave '{k}'");
254	                if (caso.PalabrasClaveAlguna is { Count: > 0 } alg && !alg.Any(k => n.Contains(Normalizar(k))))
255	                    r.Motivos.Add($"ninguna de las palabras alternativas: {string.Join(", ", alg)}");
256	                foreach (var k in caso.PalabrasProhibidas ?? new())
257	                    if (n.Contains(Normalizar(k))) r.Motivos.Add($"aparece palabra prohibida '{k}'");
258	            }
259	        }
260	    }
261	
262	    /// <summary>R2: ni ids ni nombres de estudiantes no visibles, ni la llave, en ningún cuerpo.</summary>
263	    static void ReglaR2(Caso caso, string cuerpo, Corpus corpus, string? llave, ResultadoCaso r)
264	    {
265	        var textos = new List<string> { cuerpo };
266	        try
267	        {
268	            using var d = JsonDocument.Parse(cuerpo);
269	            textos.Add(TextosJson(d.RootElement));
270	        }
271	        catch (JsonException) { }
272	        var todo = Normalizar(string.Join("\n", textos));
273	        foreach (var p in corpus.Prohibidos(caso.Usuario))
274	        {
275	            if (p.Id.Length > 0 && Regex.IsMatch(todo, $@"(?<![a-z0-9]){Regex.Escape(Normalizar(p.Id))}(?![a-z0-9])"))
276	                r.ViolacionesReglasDuras.Add($"R2 id no visible en la respuesta: {p.Id}");
277	            if (p.Nombre.Length > 0 && todo.Contains(Normalizar(p.Nombre)))
278	                r.ViolacionesReglasDuras.Add($"R2 nombre no visible en la respuesta: {p.Id}");
279	        }
280	        if (!string.IsNullOrEmpty(llave) && textos.Any(t => t.Contains(llave, StringComparison.Ordinal)))
281	            r.ViolacionesReglasDuras.Add("R2 la respuesta contiene el valor de LLM_API_KEY");
282	    }
283	
284	    /// <summary>Todos los strings del JSON ya des-escapados (para ver nombres con tildes escapadas).</summary>
285	    static string TextosJson(JsonElement e)
286	    {
287	        var sb = new StringBuilder();
288	        void Rec(JsonElement x)
289	        {
290	            switch (x.ValueKind)
291	            {
292	                case JsonValueKind.String: sb.Append(x.GetString()).Append('\n'); break;
293	                case JsonValueKind.Array: foreach (var i in x.EnumerateArray()) Rec(i); break;
294	                case JsonValueKind.Object: foreach (var p in x.EnumerateObject()) Rec(p.Value); break;
295	            }
296	        }
297	        Rec(e);
298	        return sb.ToString();
299	    }
300	
301	    public static Resumen Resumir(IReadOnlyList<ResultadoCaso> rs)
302	    {
303	        var s = new Resumen { Total = rs.Count };
304	        s.SinResultado = rs.Count(x => x.Estado == Estado.SinResultado);
305	        s.ConResultado = s.Total - s.SinResultado;
306	        s.Aprobadas = rs.Count(x => x.Estado == Estado.Ok);
307	        s.Puntaje = s.ConResultado == 0 ? 0 : (double)s.Aprobadas / s.ConResultado;
308	        s.ReglasDurasOk = rs.All(x => x.ViolacionesReglasDuras.Count == 0);
309	        var con = rs.Where(x => x.Conto200).ToList();
310	        s.TokensTotales = con.Sum(x => x.Tokens);
311	        s.CostoTotalUsd = con.Sum(x => x.CostoUsd);
312	        if (con.Count > 0)
313	        {
314	            s.TokensPromedio = (double)s.TokensTotales / con.Count;
315	            s.CostoPromedioUsd = s.CostoTotalUsd / con.Count;
316	            s.CostoPor1000Usd = s.CostoPromedioUsd * 1000;
317	        }
318	        s.CodigoSalida = !s.ReglasDurasOk ? 1
319	            : s.Total == 0 || s.SinResultado > 0 ? 2
320	            : s.Puntaje >= s.Umbral ? 0 : 1;
321	        return s;
322	    }
323	}
